INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (56, 101, 'Culture', '../upload/image/20180824/20180824195345_47512.jpg', '<p></p><p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style=''font-family:Calibri, "font-size:24px;''><strong><span style="color:blue;line-height:18px;"><img alt="" src="../upload/image/20180824/20180824195151_52261.jpg"/><img alt="" src="../upload/image/20180824/20180824195151_31478.jpg"/></span></strong></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><strong><span style="color:#E53333;line-height:18px;font-family:Tahoma;font-size:18px;">Q1: Are you A Manufacturer or A Trading Company?</span></strong></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">A: we are not only More than ten years professional manufacturer. Mainly deal with oversea market’s exporting business!</span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style=''line-height:24px;font-family:Calibri, "font-size:24px;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">But also have a</span><span style="color:#E53333;font-family:Tahoma;font-size:18px;background-color:white;">specialty</span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">sales team of ages experienced international trade business. We can do transportation easily By sea, By air, By trains and by Air-express. Easily transact several transportation methods, such as mixed loading container, less than container loading, full container loading.</span></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style=''line-height:24px;font-family:Calibri, "font-size:24px;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Plus, Asia pacific industry group</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Is an integrated companies approved by China National Ministry of Foreign Trade and General Administration of Customs. The company, as a full-invested subsidiary company of Asia Pacific Industry Group Co., Limited, has its own independent import and export rights. Registered in Hefei City, Anhui Province, P.R. China.</span></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style=''line-height:24px;font-family:Calibri, "font-size:24px;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Here you’ll find up:</span><span style="color:#E53333;font-family:Tahoma;font-size:18px;background-color:white;">Highly active</span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">, very convenient, professional</span><span style="color:#333333;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;background-color:white;">specialty</span></span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">, vitality and vigor, zero-distance service!</span></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;"><strong><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Q2: Can you OEM and ODM?</span></strong></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">A: We have high-advanced production equipment to ensure the quality of buyer’s order. Meanwhile there is a dedicated design team to help with the sample artwork for free. On the other hand your design will be 100% safe under NDA.</span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;"><strong><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Q3: Can we get some samples from factory?</span></strong></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">A: Yes, you can get available sample in our stock. Free for samples, but shipping fees is for buyer’s account. And after firm order, we will return the shipping fees to buyers or deduct the shipping fees from buyer’s firm order payment.</span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;"><strong><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Q4: Can you accept the major currencies all over the world?</span></strong></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">Yes, We can. And we can accept the payment currency, such as: USD, EUR,HKD,GBP,JPY,AUD,RMB(CNY) and so forth.</span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">Asia Pacific Industry Group Co., Limited are our company who deal with our exporting business, and any other third company are not our company.</span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">Additionally, regarding to Iran buyers, we particularly issue the Kunlun bank for all of our Iran buyer, so that all of our Iran buyer can send their payment to us directly from their Iran local bank, it was convenience and safety for buyers.</span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <br/></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;"><strong><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Q5: How to control your quantity and quality?</span></strong></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">A. 1) A complete quality guarantee system: IQC→ FAS &amp; Self-checking for each process→ OQC;</span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">2) IS09001: 2008 system, SGS, BV.COTECNA, SONCAP approved</span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">3.) Third parties to inspection</span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;"><strong><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Q6: How can we get a quote?</span></strong></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">A: Buyer can get our quotation via Email (all of our email are <a href="mailto:sales@boppfilmsales.com">sales@boppfilmsales.com</a>), Tel, Fax, Mobile (cellphone) message, Skype,Wechats, or any other methods. Please offer us the specification of the product that you need, then we will quote our price to you Within 2 hours during the working time, and within 12 hours during non-working time, and Within 24 hours during the holidays.</span></p> <p><br/></p> <p><span><br/> </span></p> <p><span><br/> </span></p> <span style=''line-height:24px;font-family:Calibri, "font-size:24px;''> <p><br/></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <br/></p> </span> <p style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:20px;"><span style=''font-family:"''><img alt="" border="0" height="480" src="../images/no-photo.png" width="348"/><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> The spirit of Mount Huangshan pine</span><br/> <br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> To headwind Aoxue self-reliance spirit</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Indomitable fighting spirit</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Indomitable enterprising spirit</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Congregation wood forest solidarity</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Guang Ying universally spirit of openness</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Wholehearted dedication</span></span></span></p> <p style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:20px;"><span style=''font-family:"''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Taiwanensis spirit is a kind of national spirit, a spirit of the times.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> We should learn taiwanensis glorify taiwanensis spirit, let taiwanensis spirit passed on from generation to generation.</span><br/> <br/> <br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Huishang spirit</span></span></span></p> <p style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:20px;"><span style=''font-family:"''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Patriotic An Min patriotism</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Indomitable enterprising spirit</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> The spirit of the trend of the degree of potential competition</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Thrifty spirit of the benefits without costs</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Dedication of the justice system Lee</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> The cultural spirit of Confucianism as well</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> A public Bangzhong team spirit</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Dedication of loyal and dedicated</span></span></span></p> <p style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:20px;"><span style=''font-family:"''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">The emblem of culture shaping the Huizhou merchants the character - Rushang, Confucian culture to guide business</span>.</span></span></p>', '2026-09-06 20:58:45');